let channel = try await ClientBootstrap(group: group).connect(host: "peer2", port: 9002).get()
var buf = channel.allocator.buffer(capacity: 64)          // forwarder
buf.writeInteger(UInt32(payload.count)); buf.writeBytes(payload)
try await channel.writeAndFlush(buf).get()

func channelRead(context: ChannelHandlerContext, data: NIOAny) {   // receiver
    var frame = unwrapInboundIn(data)
    guard let len: UInt32 = frame.readInteger(),
          let body = frame.readBytes(length: Int(len)) else { return }
    dispatch(decode(body))                                // peer method
}
